<?php use VO\Support\Template; ob_start(); ?>
<h1>Editar producto</h1><?php foreach ($errors as $e): ?><p class="error"><?= Template::e($e) ?></p><?php endforeach; ?>
<form method="post" action="/admin/producto/<?= (int)$item['id'] ?>" class="card"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><label>Nombre <input name="name" value="<?= Template::e($item['name']) ?>"></label><label>Slug <input name="slug" value="<?= Template::e($item['slug']) ?>"></label><label>Tipo <select name="type"><option value="product" <?= $item['type']==='product'?'selected':'' ?>>Producto</option><option value="service" <?= $item['type']==='service'?'selected':'' ?>>Servicio</option></select></label><label>Precio base en centavos <input name="base_price_cents" value="<?= Template::e($item['base_price_cents']) ?>"></label><label><input type="checkbox" name="allows_pickup" value="1" checked> Retiro</label><label><input type="checkbox" name="allows_delivery" value="1" <?= ((int)$item['allows_delivery'])?'checked':'' ?>> Envío</label><label><input type="checkbox" name="is_active" value="1" <?= ((int)$item['is_active'])?'checked':'' ?>> Activo</label><?php foreach ($groups as $g): ?><label><input type="checkbox" name="modifier_group_id[]" value="<?= (int)$g['id'] ?>" <?= in_array((int)$g['id'], $linked, true)?'checked':'' ?>> <?= Template::e($g['name']) ?></label><?php endforeach; ?><h2>Imágenes</h2><?php foreach ($images as $img): ?><fieldset><input type="hidden" name="image_id[]" value="<?= (int)$img['id'] ?>"><label>Archivo <input name="image_filename[]" value="<?= Template::e($img['filename']) ?>"></label><label>Orden <input name="image_sort[]" value="<?= (int)$img['sort_order'] ?>"></label><label>Texto alternativo <input name="image_alt[]" value="<?= Template::e($img['alt_text'] ?? '') ?>"></label></fieldset><?php endforeach; ?><fieldset><label>Archivo nuevo <input name="image_filename[]" placeholder="foto.jpg"></label><label>Orden <input name="image_sort[]" value="0"></label><label>Texto alternativo <input name="image_alt[]" placeholder="Descripción de la imagen"></label></fieldset><button class="btn">Guardar cambios</button></form>
<form method="post" action="/admin/producto/<?= (int)$item['id'] ?>/archivar"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><button class="btn secondary">Archivar producto</button></form>
<?php $content = ob_get_clean(); $title = 'Editar producto'; require __DIR__ . '/layout.php'; ?>
